icons.edit="<path d=\"m15 5 4 4M4 20l3.5-.8L19 7.7a2.1 2.1 0 0 0-3-3L4.5 16.2z\"/>";icons.user="<circle cx=\"12\" cy=\"8\" r=\"3\"/><path d=\"M5 21a7 7 0 0 1 14 0\"/>";icons.logout="<path d=\"M10 17l5-5-5-5M15 12H3M21 19V5a2 2 0 0 0-2-2h-5\"/>";icons.headphones="<path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/><path d=\"M4 14h2v5H4a2 2 0 0 1-2-2v-1a2 2 0 0 1 2-2Zm16 0h-2v5h2a2 2 0 0 0 2-2v-1a2 2 0 0 0-2-2Z\"/>";
icons.map='<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>';icons.lock='<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>';icons.trophy='<path d="M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6m-4 1h8"/>';
icons.down="<path d=\"m6 9 6 6 6-6\"/>";icons.left='<path d="m15 6-6 6 6 6"/>';icons.right='<path d="m9 6 6 6-6 6"/>';icons.queue='<path d="M4 7h14M4 12h10M4 17h7"/><path d="m17 13.5 5 3.5-5 3.5z"/>';icons.clock='<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 1.9"/>';const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const stories=[{id:'noah',title:'Uma arca cheia de amor',subtitle:'Noé e a promessa de Deus',image:'noah-ark',category:'Aventuras',tag:'Para se encantar',age:'3–8 anos',ref:'Gênesis 6–9',description:'Embarque com Noé e seus amigos animais em uma aventura sobre confiança, cuidado e uma promessa colorida no céu.'},{id:'david',title:'Pequeno pastor, grande coração',subtitle:'Davi e o cuidado de Deus',image:'david-shepherd',category:'Coragem',tag:'Pequenos corajosos',age:'3–8 anos',ref:'1 Samuel 16 · Salmo 23',description:'Entre colinas e ovelhinhas, Davi descobre que um coração cheio de fé pode encontrar coragem nas pequenas coisas.'},{id:'night',title:'Paz no barquinho',subtitle:'Um descanso nos braços de Jesus',image:'jesus-night',category:'Para dormir',tag:'Hora de aconchegar',age:'3–8 anos',ref:'Marcos 4:35–41',description:'A noite chegou. Deixe as preocupações na margem e embarque em uma história tranquila sobre confiar no cuidado de Jesus.'}];
stories.push({id:'promise',title:'As cores de uma promessa',subtitle:'Depois da chuva, um recomeço',image:'noah-ark',category:'Aventuras',tag:'Novos começos',age:'3–8 anos',ref:'Gênesis 9:12–17',description:'Depois de uma longa chuva, um arco-íris ensina a Noé que cada novo dia pode trazer esperança.'},{id:'shepherd',title:'Você nunca está sozinho',subtitle:'O carinho do bom pastor',image:'david-shepherd',category:'Coragem',tag:'Deus cuida de mim',age:'3–8 anos',ref:'Salmo 23',description:'Uma caminhada por campos tranquilos para lembrar que somos amados e que podemos pedir ajuda.'},{id:'thanks',title:'Um céu de agradecimentos',subtitle:'Pequenas coisas, grandes presentes',image:'jesus-night',category:'Para dormir',tag:'Gratidão',age:'3–8 anos',ref:'Salmo 136:1',description:'Antes de dormir, descubra como as pequenas alegrias do dia podem se transformar em uma oração de gratidão.'});

if(window.STORY_CATALOG?.length)stories.splice(0,stories.length,...window.STORY_CATALOG);
var gardenModules=["Antigo Testamento","Vida de Jesus","Parábolas de Jesus","Depois de Jesus","Fé e Valores"];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let favorites=read('sementinha-favorites',[]),page='journey',filter='Todas',query='',searchOpen=false,current=stories.find(s=>s.id===read('sementinha-last','noah'))||stories[0],timer=null,timerMinutes=0,speed=1;
const audio=document.getElementById('audio');audio.src=current.catalogOnly?"":"/assets/"+current.id+".m4a";const app=document.getElementById('app');const asset=s=>`/assets/${s.image}.${s.catalogOnly?'png':'jpg'}`;const fmt=t=>Number.isFinite(t)?`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`:'0:00';
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),2800)}
function nav(){return `<aside class="sidebar"><div class="brand">${icon('sprout')}<span class="brand-name">sementinha<em>da fé</em></span></div><div class="brand-sub">pequenas histórias. grande amor.</div><nav class="nav" aria-label="Navegação principal">${[['home','home','Início'],['journey','map','Jornada'],['library','book','Histórias'],['favorites','heart','Favoritas'],['parents','user','Perfil']].map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('sprout')}Cada história ouvida<br>é uma sementinha de amor.</div><button class="parents" data-page="parents">${icon('user')}Perfil</button></div></aside>`}
function card(s){return `<button class="lb-card lb-card--${PLAYER_TINTS[s.category]||'violet'}" data-story="${s.id}" aria-label="Ouvir ${s.title}"><span class="lb-cover"><img src="${asset(s)}" alt="" loading="lazy"><b class="lb-num">${storyNumber(s)}</b>${s.catalogOnly?`<span class="lb-soon">${icon('clock')}Em breve</span>`:''}<span class="lb-play">${icon('play')}</span></span><span class="lb-body"><strong>${s.title}</strong><small>${s.category} <i aria-hidden="true">·</i> ${s.age}</small></span></button>`}function storyGroups(list,grouped=true){if(!grouped)return[{name:'',i:-1,items:list}];const groups=gardenModules.map((name,i)=>({name,i,items:list.filter(s=>s.category===name)})).filter(g=>g.items.length),others=list.filter(s=>!gardenModules.includes(s.category));if(others.length)groups.push({name:'Outras histórias',i:-1,items:others});return groups}function renderGroups(groups){return groups.map(g=>`<section class="lb-group">${g.name?`<header class="lb-group-head"><span class="lb-group-num">${g.i>=0?'Jardim '+(g.i+1):''}</span><h2>${g.name}</h2><small>${g.items.length} ${g.items.length===1?'história':'histórias'}</small></header>`:''}<div class="lb-grid">${g.items.map(card).join('')}</div></section>`).join('')}
function chips(){return `<div class="lb-filters" role="group" aria-label="Categorias">${[['Todas','star'],['Antigo Testamento','book'],['Vida de Jesus','sun'],['Parábolas de Jesus','leaf'],['Depois de Jesus','sprout'],['Fé e Valores','heart']].map(([t,i])=>`<button data-filter="${t}" class="lb-chip lb-chip--${PLAYER_TINTS[t]||'aqua'} ${filter===t?'active':''}" aria-pressed="${filter===t}">${icon(i)}${t==='Todas'?'Todas as histórias':t}</button>`).join('')}</div>`}
function hero(s,sleep=false){return `<section class="hero"><img class="hero-art" src="${asset(s)}" alt="${s.subtitle}"><div class="hero-copy"><div class="eyebrow">${icon(sleep?'moon':'sun')}${sleep?'Um abraço antes de dormir':'A história de hoje'}</div><h2>${s.title}</h2><p>${sleep?'Respire devagar. Jesus cuida de você, até enquanto você sonha.':'Uma aventura sobre confiar em Deus e cuidar uns dos outros.'}</p><div class="hero-bottom"><button class="primary" data-story="${s.id}">${icon('play')}${sleep?'Ouvir e descansar':'Vamos ouvir'}</button><span class="small">${s.age}</span></div></div></section>`}
function home(){const catalog=window.STORY_CATALOG||[],last=read('sementinha-last',null)?[...stories,...catalog].find(s=>s.id===read('sementinha-last',null)):null;return `<div class="heading"><div><div class="chapter-label">Pequenos de Fé</div><h1>Um mundo de histórias<br>para descobrir.</h1><p>Escolha uma história, imagine junto e cresça em fé.</p></div><span class="tiny-sun">${icon('sun')}</span></div>${last?`<section class="lb-continue" aria-label="Continue ouvindo"><button class="lb-continue-cover" data-story="${last.id}" aria-label="Continuar ${last.title}"><img src="${asset(last)}" alt="">${icon('play')}</button><div class="lb-continue-body"><span class="lb-kicker lb-kicker--live"><i aria-hidden="true"></i>Continue ouvindo</span><h2>${last.title}</h2><p>${last.category} <i aria-hidden="true">·</i> ${last.ref}</p><button class="primary" data-story="${last.id}">${icon('play')}Continuar história</button></div></section>`:`<button class="lb-continue lb-continue--start" data-page="journey"><div class="lb-continue-body"><span class="lb-kicker">${icon('sprout')}Sua jornada começa aqui</span><h2>Começar jornada</h2><p>Descubra histórias, ouça com calma e cultive momentos de fé.</p><span class="primary">${icon('map')}Abrir jornada</span></div>${icon('sprout')}</button>`}<section class="lb-home-all"><header class="lb-group-head"><span class="lb-group-num">${catalog.length} histórias em ${gardenModules.length} jardins</span><h2>Todas as histórias</h2></header>${renderGroups(storyGroups(catalog))}</section><p class="footer-note">Feito para pequenos ouvidos. E grandes corações.</p>`}
function content(){if(page=='home'&&!query&&filter=='Todas')return home();if(page=='journey'&&!query)return journey();if(page=='parents')return profilePage();if(page==='parents')return `<div class="page-intro"><h1>Seu perfil</h1><p>Cuide da sua jornada e das preferências da família.</p></div><section class="parent-panel"><h2>Feito para ouvir juntinhos</h2><p>A jornada abre uma nova descoberta a cada história ouvida. Os dias de escuta, as etapas e o tema escolhido ficam guardados neste navegador.</p><p>As histórias são adaptações infantis inspiradas na Bíblia. Depois de ouvir, conversem sobre o que mais tocou o coração de vocês.</p><div class="settings-row"><div><strong>Sobre os áudios</strong><small>Esta é uma versão de demonstração.</small></div>${icon('book')}</div><p>As seis histórias têm narração sintética demonstrativa. Os arquivos podem ser substituídos por gravações definitivas.</p><div class="settings-row"><div><strong>Desligar o áudio em</strong><small>Um descanso sem pressa.</small></div>${timerSelect()}</div><div class="settings-row"><div><strong>Suas histórias favoritas</strong><small>Salvas somente neste navegador.</small></div><button class="text-button" data-page="favorites">Ver ${icon('arrow')}</button></div><div class="settings-row"><div><strong>Idade sugerida</strong><small>3 a 8 anos, com acompanhamento de um adulto.</small></div>${icon('heart')}</div></section>`;
if(page==='home'&&!query&&filter==='Todas')return `<div class="heading"><div><h1>O amor cresce<br>a cada história.</h1><p>Qual aventura vamos viver juntos hoje?</p></div><span class="tiny-sun">${icon('sun')}</span></div><div class="home-feature">${hero(stories[0])}<button class="journey-invite" data-page="journey"><span class="chapter-label">Seu pequeno grande caminho</span>${icon('map')}<h2>Vamos explorar<br>o Jardim da Fé?</h2><span>${journeyCount()} de 6 descobertas ${icon('arrow')}</span></button></div>${chips()}<div class="section-head"><h2>Um mundo de histórias</h2><button class="text-button" data-page="library">Explorar todas ${icon('arrow')}</button></div><div class="cards home-cards">${stories.slice(0,3).map(card).join('')}</div><section class="night-banner"><img class="night-image" src="${asset(stories[2])}" alt="Barco tranquilo sob o céu estrelado" loading="lazy"><div class="night-copy">${icon('moon')}<h2>O dia termina. O amor fica.</h2><p>Histórias calminhas para sonhos bonitos.</p><button class="text-button" data-page="sleep">Vamos desacelerar ${icon('arrow')}</button></div></section><p class="footer-note">Feito para pequenos ouvidos. E grandes corações.</p>`;
if(page==='sleep'&&!query)return `<div class="page-intro"><h1>Boa noite, pequeno coração.</h1><p>Um último abraço em forma de história.</p></div>${hero(stories[2],true)}<section class="parent-panel"><h2>Vamos preparar o soninho?</h2><p>Diminua a luz, encontre uma posição gostosa e respire bem devagar. Agora é só ouvir.</p><div class="settings-row"><div><strong>Hora de descansar</strong><small>O áudio pausa quando o tempo terminar.</small></div>${timerSelect()}</div></section>`;
const allStories=stories;let list=allStories.filter(s=>(page!=='favorites'||favorites.includes(s.id))&&(filter==='Todas'||s.category===filter)&&`${s.title} ${s.subtitle} ${s.category}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));const grouped=page!=='favorites',kicker=page==='favorites'?`${icon('heart')}${list.length} ${list.length===1?'história guardada':'histórias guardadas'}`:query?`${icon('search')}${list.length} ${list.length===1?'resultado':'resultados'}`:`${icon('book')}${stories.length} histórias em ${gardenModules.length} jardins`;return `<section class="lb-intro"><div class="lb-kicker">${kicker}</div><h1>${page==='favorites'?'Histórias guardadas no coração':query?'Encontre sua próxima história':'Toda história é uma descoberta'}<span>.</span></h1><p>${page==='favorites'?'Aquelas que a gente quer ouvir mais uma vez.':'Escolha uma capa. A aventura começa no play.'}</p></section>${chips()}${list.length?renderGroups(storyGroups(list,grouped)):`<div class="lb-empty">${icon(page==='favorites'?'heart':'search')}<h3>${page==='favorites'?'Seu coração tem espaço para histórias.':'Ainda não encontramos essa história.'}</h3><p>${page==='favorites'?'Toque no coração do player para guardar suas preferidas aqui.':'Experimente outro nome ou escolha uma categoria.'}</p><button class="primary" data-page="library">Explorar histórias</button></div>`}`}
function timerSelect(){return `<select aria-label="Temporizador de descanso" data-timer>${[0,5,10,15,30].map(n=>`<option value="${n}" ${timerMinutes===n?'selected':''}>${n?n+' minutos':'Desativado'}</option>`).join('')}</select>`}
function favoriteButton(){return `<button class="icon-btn favorite ${favorites.includes(current.id)?'fav-on':''}" data-favorite aria-label="${favorites.includes(current.id)?'Remover dos favoritos':'Adicionar aos favoritos'}" aria-pressed="${favorites.includes(current.id)}">${icon('heart')}</button>`}
function mini(){return `<section class="mini" aria-label="Player de áudio"><button class="mini-info" data-open-player aria-label="Abrir player"><img src="${asset(current)}" alt=""><span><strong>${current.title}</strong><small>${current.catalogOnly?'Áudio em preparação':'Narração demonstrativa'}</small></span></button><div class="mini-center"><div class="controls"><button class="icon-btn" data-skip="-15" aria-label="Voltar 15 segundos">${icon('back')}</button><button class="round-play" data-toggle aria-label="Reproduzir">${icon(audio.paused?'play':'pause')}</button><button class="icon-btn" data-skip="15" aria-label="Avançar 15 segundos">${icon('next')}</button></div><div class="mini-range"><span data-elapsed>${fmt(audio.currentTime)}</span><input data-seek type="range" min="0" max="100" value="0" aria-label="Posição do áudio"><span data-duration>${fmt(audio.duration)}</span></div></div><div class="mini-right">${favoriteButton()}${icon('volume')}<input type="range" data-volume min="0" max="1" step=".05" value="${audio.volume}" aria-label="Volume"><button class="icon-btn" data-open-player aria-label="Expandir player">${icon('expand')}</button></div></section>`}
function render(){if(!read('sementinha-session-active',true)){app.innerHTML=loginView();return}const p=profileInfo(),avatar=p.avatar?`<img src="${p.avatar}" alt="Foto de perfil de ${p.name}">`:`<span aria-hidden="true">${p.name.trim().charAt(0).toUpperCase()||'S'}</span>`;document.documentElement.dataset.theme=theme;app.innerHTML=`${nav()}<main class="main ${page==='sleep'?'night-mode':''}"><header class="topbar"><div class="hello"><strong>Olá, que bom ter você aqui!</strong>Vamos cultivar coisas boas?</div><div class="brand mobile-brand">${icon('sprout')}<span class="brand-name">sementinha<em>da fé</em></span></div><div class="top-actions">${themeButton()}<button class="search-trigger" data-open-search aria-label="Pesquisar histórias">${icon('search')}</button><label class="search ${searchOpen?'is-open':''}">${icon('search')}<input id="search" type="search" placeholder="Buscar uma história" aria-label="Buscar uma história"></label><button class="avatar" data-page="parents" aria-label="Abrir perfil">${avatar}</button></div></header><div id="content">${content()}</div></main>${mini()}<dialog class="np-dialog" id="player" aria-label="Player de histórias"></dialog><dialog class="stage-dialog" id="stage-dialog" aria-label="Sua próxima descoberta"></dialog>`;document.getElementById('search').value=query;if(searchOpen)requestAnimationFrame(()=>document.getElementById('search')?.focus());sync();if(page==='journey')afterJourneyRender()}
const PLAYER_TINTS={'Antigo Testamento':'gold','Vida de Jesus':'aqua','Parábolas de Jesus':'pink','Depois de Jesus':'lilac','Fé e Valores':'coral'};function storyNumber(s){const i=stories.findIndex(x=>x.id===s.id);return String((i<0?0:i)+1).padStart(2,'0')}function remainingLabel(){return Number.isFinite(audio.duration)?`-${fmt(Math.max(0,audio.duration-audio.currentTime))}`:'-0:00'}function speedLabel(){return speed===.75?'0,75x':speed===1.25?'1,25x':speed===1.5?'1,50x':speed+'x'}
function openPlayer(){const d=document.getElementById('player'),liked=favorites.includes(current.id);d.innerHTML=`<div class="np np--${PLAYER_TINTS[current.category]||'violet'}"><div class="np-sky" aria-hidden="true">${Array.from({length:12},(_,i)=>`<span style="--i:${i};--left:${(i*37+11)%94}%;--top:${(i*23+9)%86}%"></span>`).join('')}</div><header class="np-top"><button class="np-chip ${liked?'fav-on':''}" data-favorite aria-pressed="${liked}" aria-label="${liked?'Remover dos favoritos':'Adicionar aos favoritos'}">${icon('heart')}</button><button class="np-chip" data-close-player aria-label="Fechar player">${icon('close')}</button></header><div class="np-stage"><div class="np-art"><img src="${asset(current)}" alt="${current.subtitle}"><span class="np-seal" aria-hidden="true">${icon('sprout')}<b>${storyNumber(current)}</b></span></div></div><div class="np-head"><h2>${current.title}</h2><button class="np-queue" data-player-page="library" aria-label="Ver todas as histórias">${icon('queue')}</button></div><p class="np-ref">${icon('book')}${current.ref}</p>${current.catalogOnly?`<p class="np-soon">${icon('clock')}Áudio em preparação</p>`:''}<div class="np-eq" aria-hidden="true">${Array.from({length:4},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="np-scrub"><input data-seek type="range" min="0" max="100" step=".1" value="0" aria-label="Posição do áudio"><div class="np-times"><span data-elapsed>${fmt(audio.currentTime)}</span><span data-remaining>${remainingLabel()}</span></div></div><div class="np-controls"><button class="np-skip" data-skip="-15" aria-label="Voltar 15 segundos">${icon('back')}<b>15</b></button><button class="np-play" data-toggle aria-label="Reproduzir">${icon(audio.paused?'play':'pause')}</button><button class="np-skip" data-skip="15" aria-label="Avançar 15 segundos">${icon('next')}<b>15</b></button></div><button class="np-speed" data-speed aria-label="Alterar velocidade da narração">${speedLabel()}</button></div>`;d.showModal();sync()}
async function play(){if(current.catalogOnly){toast("O áudio desta história estará disponível em breve.");return}try{if(!current.catalogOnly&&!isUnlocked(current.id)){current=stories[journeyCount()]||stories[0];audio.src=current.catalogOnly?"":"/assets/"+current.id+".m4a";render();openPlayer()}await startAudioVisualization();await audio.play()}catch{toast('Não foi possível tocar o áudio. Toque em play para tentar novamente.')}}
function sync(){document.body.classList.toggle('is-playing',!audio.paused);document.querySelectorAll('[data-playing-label]').forEach(e=>e.textContent=audio.paused?'Uma pausa para imaginar':'Deixe a história te levar');document.querySelectorAll('[data-toggle]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Reproduzir':'Pausar')});document.querySelectorAll('[data-elapsed]').forEach(e=>e.textContent=fmt(audio.currentTime));document.querySelectorAll('[data-duration]').forEach(e=>e.textContent=fmt(audio.duration));document.querySelectorAll('[data-remaining]').forEach(e=>e.textContent=remainingLabel());document.querySelectorAll('[data-seek]').forEach(e=>{e.value=audio.duration?audio.currentTime/audio.duration*100:0;e.style.setProperty('--seek',(audio.duration?audio.currentTime/audio.duration*100:0)+'%');e.disabled=!Number.isFinite(audio.duration);e.setAttribute('aria-valuetext',`${fmt(audio.currentTime)} de ${fmt(audio.duration)}`)})}
app.addEventListener('click',e=>{if(searchOpen&&!query.trim()&&!e.target.closest('.search')&&!e.target.closest('[data-open-search]')){searchOpen=false;render();return}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-open-search')){searchOpen=true;render();return}if(b.hasAttribute("data-close-player")){const d=document.getElementById("player");d.classList.add("closing");setTimeout(()=>{d.classList.remove("closing");d.close();if(progressPending)revealProgress()},220);return}if(b.dataset.gardenStory){if(!isUnlocked(b.dataset.gardenStory)){toast("Ouça a história anterior para desbloquear esta sementinha.");return}startStory(b.dataset.gardenStory);return}if(b.dataset.playerPage){document.getElementById("player").close();page=b.dataset.playerPage;filter="Todas";query="";render();window.scrollTo({top:0,behavior:"instant"});return}if(b.dataset.peek){showStage(b.dataset.peek);return}if(b.hasAttribute('data-close-stage')){document.getElementById('stage-dialog').close();return}if(b.hasAttribute('data-stage-play')){document.getElementById('stage-dialog').close();startStory(b.dataset.stagePlay);return}if(b.hasAttribute('data-toggle-theme')){theme=theme==='dark'?'light':'dark';save('sementinha-theme',theme);document.documentElement.dataset.theme=theme;document.querySelectorAll('button[data-toggle-theme]').forEach(x=>{x.innerHTML=icon(theme==='dark'?'sun':'moon');x.setAttribute('aria-label',theme==='dark'?'Ativar tema claro':'Ativar tema escuro')});return}if(b.dataset.month){monthOffset+=Number(b.dataset.month);refreshActivity();return}if(b.hasAttribute('data-next-stage')){document.getElementById('player').close();startStory(stories[Math.min(journeyCount(),stories.length-1)].id);return}if(b.hasAttribute('data-jump-current')){scrollToCurrent(true);return}if(b.dataset.page){page=b.dataset.page;filter='Todas';query='';render();window.scrollTo({top:0,behavior:'instant'})}else if(b.dataset.filter){filter=b.dataset.filter;document.getElementById('content').innerHTML=content()}else if(b.dataset.story){searchOpen=false;startStory(b.dataset.story)}else if(b.hasAttribute('data-toggle')){audio.paused?play():audio.pause()}else if(b.dataset.skip){if(Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(audio.duration,audio.currentTime+Number(b.dataset.skip)))}else if(b.hasAttribute('data-open-player'))openPlayer();else if(b.hasAttribute('data-close-player'))document.getElementById('player').close();else if(b.hasAttribute('data-favorite')){const liked=favorites.includes(current.id);favorites=liked?favorites.filter(x=>x!==current.id):[...favorites,current.id];save('sementinha-favorites',favorites);document.querySelectorAll('[data-favorite]').forEach(x=>{x.classList.toggle('fav-on',!liked);x.setAttribute('aria-pressed',!liked);x.setAttribute('aria-label',liked?'Adicionar aos favoritos':'Remover dos favoritos')});if(page==='favorites')document.getElementById('content').innerHTML=content();toast(liked?'História removida das favoritas.':'Guardada com carinho nas favoritas.')}else if(b.hasAttribute('data-speed')){speed=({1:1.25,1.25:1.5,1.5:2,2:.75,.75:1})[speed];audio.playbackRate=speed;b.textContent=speedLabel()}});
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.getElementById('content').innerHTML=content()}if(e.target.hasAttribute('data-seek')&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(e.target.value)/100;if(e.target.hasAttribute('data-volume'))audio.volume=Number(e.target.value)});
app.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter'){e.preventDefault();searchOpen=false;render()}});
app.addEventListener('change',e=>{if(e.target.hasAttribute('data-timer')){clearTimeout(timer);timerMinutes=Number(e.target.value);document.querySelectorAll('[data-timer]').forEach(x=>x.value=timerMinutes);if(timerMinutes){timer=setTimeout(()=>{audio.pause();timerMinutes=0;document.querySelectorAll('[data-timer]').forEach(x=>x.value=0);toast('É hora de descansar. Boa noite!')},timerMinutes*60000);toast(`O áudio vai pausar em ${timerMinutes} minutos.`)}else toast('Temporizador desativado.')}});
['timeupdate','loadedmetadata','play','pause','ended','durationchange'].forEach(x=>audio.addEventListener(x,sync));audio.addEventListener('error',()=>{if(!current.catalogOnly)toast('O áudio não carregou. Tente novamente.')});

let theme=read('sementinha-theme',window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
let journeyData=read('sementinha-journey',{completed:[],days:{},coverage:{}});if(!journeyData||!Array.isArray(journeyData.completed)||!journeyData.days||!journeyData.coverage)journeyData={completed:[],days:{},coverage:{}};
let monthOffset=0,lastAudioPosition=0,lastSaveAt=0;const ACTIVE_DAY_SECONDS=15;function activeDayCount(){return Object.values(journeyData.days).filter(s=>s>=ACTIVE_DAY_SECONDS).length}audio.addEventListener('seeking',()=>{lastAudioPosition=audio.currentTime});audio.addEventListener('loadedmetadata',()=>{lastAudioPosition=0});audio.addEventListener('timeupdate',()=>{const pos=audio.currentTime,delta=pos-lastAudioPosition;lastAudioPosition=pos;if(audio.paused||!(delta>0)||delta>2)return;const key=dateKey(),before=journeyData.days[key]||0,after=before+delta;journeyData.days[key]=after;const lit=before<ACTIVE_DAY_SECONDS&&after>=ACTIVE_DAY_SECONDS,now=Date.now();if(lit||now-lastSaveAt>4000){save('sementinha-journey',journeyData);lastSaveAt=now}if(lit){refreshActivity();toast('Mais um dia ativo! Sua chama continua acesa.')}trackCoverage(pos)});let openingGate=-1,progressPending=false;function trackCoverage(pos){if(current.catalogOnly||journeyData.completed.includes(current.id))return;const sec=Math.floor(pos),cov=journeyData.coverage[current.id]||(journeyData.coverage[current.id]=[]);if(cov.includes(sec))return;cov.push(sec);if(Number.isFinite(audio.duration)&&audio.duration>0&&cov.length>=Math.floor(audio.duration*.9))finishStage()}audio.addEventListener('ended',()=>{if(current.catalogOnly)return;const cov=journeyData.coverage[current.id]||[];if(Number.isFinite(audio.duration)&&cov.length>=Math.floor(audio.duration*.85))finishStage()});function finishStage(){if(journeyData.completed.includes(current.id))return;const idx=stories.findIndex(s=>s.id===current.id);if(idx!==journeyCount())return;journeyData.completed.push(current.id);save('sementinha-journey',journeyData);const zones=journeyZones(),next=zones.findIndex(z=>z.start===idx+1);progressPending=true;if(next>0){openingGate=next;toast(`Portão aberto! Bem-vindo ao Jardim ${next+1} · ${zones[next].category}`)}else toast(idx+1<stories.length?'História concluída! A próxima já está aberta.':'Você completou toda a jornada!');revealProgress()}function revealProgress(){refreshMap();if(!document.getElementById('player')?.open)requestAnimationFrame(()=>scrollToCurrent(true))}


function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function journeyCount(){let n=0;for(const s of stories){if(!journeyData.completed.includes(s.id))break;n++}return n}
function isUnlocked(id){return stories.findIndex(s=>s.id===id)<=journeyCount()}
function themeButton(){return `<button class="icon-btn theme-toggle" data-toggle-theme aria-label="${theme==='dark'?'Ativar tema claro':'Ativar tema escuro'}">${icon(theme==='dark'?'sun':'moon')}</button>`}
function startStory(id){const next=[...stories,...(window.STORY_CATALOG||[])].find(s=>s.id===id);if(!next)return;if(!next.catalogOnly&&!isUnlocked(id)){toast('Uma descoberta de cada vez. Ouça a etapa anterior para abrir este caminho.');return}if(current.id!==next.id){current=next;audio.src=next.catalogOnly?"":"/assets/"+current.id+".m4a";audio.playbackRate=speed;lastAudioPosition=0;save('sementinha-last',current.id);render()}openPlayer();if(!current.catalogOnly)play()}
function flameMascot(){return `<svg class="jy-flame" viewBox="0 0 140 150" aria-hidden="true"><defs><linearGradient id="jy-fo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffc247"/><stop offset="1" stop-color="#ff6b2c"/></linearGradient><linearGradient id="jy-fi" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff6b3"/><stop offset="1" stop-color="#ffd23f"/></linearGradient></defs><g class="jy-rays"><path d="M20 60 8 56M24 46l-10-8M32 34l-6-12M120 60l12-4M116 46l10-8M108 34l6-12"/></g><g class="jy-body"><path class="jy-outer" d="M70 6C74 30 106 42 106 82c0 30-16 58-36 58S34 112 34 82c0-16 8-26 14-38 2 12 8 18 12 18-4-18 0-36 10-56z"/><path class="jy-inner" d="M70 58c4 16 24 22 24 44 0 15-10 25-24 25S46 117 46 102c0-10 6-16 10-26 2 8 6 10 8 10-2-10 0-18 6-28z"/><path class="jy-eye" d="M55 100q6-7 12 0M73 100q6-7 12 0"/><circle class="jy-cheek" cx="51" cy="109" r="5"/><circle class="jy-cheek" cx="89" cy="109" r="5"/><path class="jy-smile" d="M62 110q8 8 16 0"/></g><g class="jy-hand jy-hand-l"><path d="M36 100c-8 0-14-4-18-10"/><circle cx="16" cy="87" r="7"/></g><g class="jy-hand jy-hand-r"><path d="M104 100c8 0 14-4 18-10"/><circle cx="124" cy="87" r="7"/></g></svg>`}function sproutArt(){return `<svg viewBox="0 0 200 170" aria-hidden="true"><defs><linearGradient id="jy-soil" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9a6540"/><stop offset="1" stop-color="#47281a"/></linearGradient><linearGradient id="jy-leaf" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stop-color="#1fb389"/><stop offset="1" stop-color="#93f7d6"/></linearGradient></defs><g class="jy-spark"><path d="M26 44l8 8M34 44l-8 8M164 26l8 8M172 26l-8 8M178 66h10M183 61v10"/></g><path d="M22 140c6-30 40-48 78-48s72 18 78 48c4 16-30 22-78 22S18 156 22 140z" fill="url(#jy-soil)"/><ellipse cx="60" cy="120" rx="6" ry="4" fill="#33190b" opacity=".5"/><ellipse cx="132" cy="128" rx="5" ry="3.5" fill="#33190b" opacity=".5"/><ellipse cx="98" cy="146" rx="7" ry="4" fill="#33190b" opacity=".35"/><path d="M100 110c0-16-2-30-6-46" fill="none" stroke="#2e9c6a" stroke-width="6" stroke-linecap="round"/><path d="M94 66C70 66 50 48 52 22c26 0 44 20 42 44z" fill="url(#jy-leaf)"/><path d="M96 58c26-4 46-26 42-52C112 10 94 32 96 58z" fill="url(#jy-leaf)"/><path d="M90 60C78 52 66 40 60 30M98 54c10-12 20-24 30-36" fill="none" stroke="#e9fff7" stroke-width="2" stroke-linecap="round" opacity=".55"/></svg>`}
function calendar(){const now=new Date(),month=new Date(now.getFullYear(),now.getMonth()+monthOffset,1),count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),pad=month.getDay(),tail=(7-(pad+count)%7)%7,todayKey=dateKey(),name=month.toLocaleDateString('pt-BR',{month:'long'}),title=name.charAt(0).toUpperCase()+name.slice(1);return `<section class="jy-cal" aria-label="Calendário de escuta"><div class="jy-cal-head"><h3>${title}</h3><div class="jy-cal-nav"><button data-month="-1" aria-label="Mês anterior">${icon('left')}</button><span>${title} ${month.getFullYear()}</span><button data-month="1" aria-label="Próximo mês" ${monthOffset>=0?'disabled':''}>${icon('right')}</button></div></div><div class="jy-cal-grid">${['D','S','T','Q','Q','S','S'].map(t=>`<span class="jy-wd">${t}</span>`).join('')}${'<span></span>'.repeat(pad)}${Array.from({length:count},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i+1),k=dateKey(d),done=(journeyData.days[k]||0)>=ACTIVE_DAY_SECONDS,today=k===todayKey,future=k>todayKey;return `<span class="jy-day ${done?'listened':''} ${today?'today':''} ${future?'future':''}" title="${d.toLocaleDateString('pt-BR')}${done?' · Dia com história':''}">${i+1}${done?`<i>${icon('check')}</i>`:''}</span>`}).join('')}${'<span class="jy-dot">·</span>'.repeat(tail)}</div><div class="jy-cal-legend"><span><i>${icon('check')}</i>Dia com história</span><span><i class="jy-lg-today"></i>Hoje</span></div></section>`}
function journey(){return `<section class="jy-hero"><div class="jy-hero-copy"><div class="jy-kicker">${icon('sprout')}Sua jornada com Deus</div><h1>Um jardim de<br>descobertas<span>.</span></h1><p>Avance uma história por vez. Cada escuta abre o próximo caminho.</p></div><div class="jy-art" aria-hidden="true">${sproutArt()}<span class="jy-note">Pequenas escutas, grandes propósitos.<i>${icon('heart')}</i></span></div></section>${activeDaysPanel()}${journeyMap()}<button class="jm-here" data-jump-current hidden>${icon('map')}Você está aqui</button><p class="footer-note">Cada história abre o próximo passo do caminho.</p>`}
function activeDaysPanel(){const active=activeDayCount();return `<section class="jy-activity" data-activity aria-label="Dias ativos e calendário"><div class="jy-flame-card"><div class="jy-flame-wrap">${flameMascot()}</div><div class="jy-flame-copy"><strong><b>${active}</b>${active===1?'dia ativo':'dias ativos'}</strong><p>Ouça uma história por dia e mantenha sua chama acesa.</p></div><div class="jy-bubble">“Com você todos os dias nessa jornada!”${icon('heart')}</div></div>${calendar()}</section>`}function refreshActivity(){const el=document.querySelector('[data-activity]');if(el)el.outerHTML=activeDaysPanel()}
var gardenBackgrounds=["garden-antigo-v2.png","garden-jesus-v3.png","garden-parabolas-v3.png","garden-depois-v3.png","garden-valores-v3.png"];
const NODE_XS=[26,54,74,56,30,44,70,50],NODE_YS=[16,26.5,37,47.5,58,68.5,79,89.5];function journeyZones(){const zones=[];stories.forEach((s,i)=>{const z=zones[zones.length-1];if(z&&z.category===s.category)z.items.push(s);else zones.push({category:s.category,start:i,items:[s]})});return zones}function zonePath(points){return points.map((p,i)=>{if(!i)return`M${p[0]} ${p[1]}`;const a=points[i-1],my=((a[1]+p[1])/2).toFixed(1);return`C${a[0]} ${my} ${p[0]} ${my} ${p[0]} ${p[1]}`}).join(' ')}function journeyMap(){const zones=journeyZones(),done=journeyCount();return `<section class="jm" data-journey-map aria-label="Trilho da jornada">${zones.map((z,zi)=>{const tint=PLAYER_TINTS[z.category]||['gold','aqua','pink','lilac','coral'][zi%5],bg=gardenBackgrounds[zi%gardenBackgrounds.length],n=z.items.length,completed=Math.max(0,Math.min(n,done-z.start)),open=done>=z.start;const pts=z.items.map((s,i)=>[NODE_XS[i%NODE_XS.length],n===NODE_YS.length?NODE_YS[i]:((i+.5)/n)*84+8]);const road=[...(zi?[[50,0]]:[]),...pts.map(([x,y])=>[x,+(y*2.36).toFixed(1)]),...(zi<zones.length-1?[[50,236]]:[])],d=zonePath(road);const gate=zi?`<div class="jm-gate ${open?'open':'locked'} ${openingGate===zi?'opening':''}" data-gate="${zi}"><span class="jm-gate-line"></span><div class="jm-gate-arch"><div class="jm-gate-doors"><span class="jm-gate-door jm-gate-door--l"></span><span class="jm-gate-door jm-gate-door--r"></span></div><span class="jm-gate-lock">${icon(open?'check':'lock')}</span></div><div class="jm-gate-copy"><span>Jardim ${zi+1}</span><strong>${z.category}</strong><small>${open?'Portão aberto — pode entrar!':'Termine o jardim anterior para abrir'}</small></div><span class="jm-gate-line"></span></div>`:'';return `${gate}<div class="jm-zone jm-zone--${tint}" id="jardim-${zi+1}"><img class="jm-bg" src="/assets/${bg}" alt="" loading="lazy"><div class="jm-shade"></div><div class="jm-zone-head"><b>${zi+1}</b><strong>${z.category}</strong><small>${completed}/${n}</small></div><svg class="jm-path" viewBox="0 0 100 236" preserveAspectRatio="none" aria-hidden="true"><path class="jm-road" d="${d}"/><path class="jm-dots" d="${d}"/></svg>${z.items.map((s,i)=>{const gi=z.start+i,unlocked=gi<=done,isDone=gi<done,isCurrent=gi===done,[x,y]=pts[i];return `<button class="jm-node ${isDone?'completed':''} ${isCurrent?'current':''} ${unlocked?'':'locked'}" style="--x:${x}%;--y:${y}%" data-garden-story="${s.id}" aria-label="${unlocked?'Ouvir':'Bloqueada'} ${s.title}"><span class="jm-node-art">${isCurrent?`<span class="jm-flag">${icon('sprout')}Você está aqui</span>`:''}<img src="${asset(s)}" alt="" loading="lazy"><b>${storyNumber(s)}</b><i>${icon(isDone?'check':unlocked?'play':'lock')}</i></span><strong>${s.title}</strong></button>`}).join('')}</div>`}).join('')}</section>`}let jmObserver=null;function scrollToCurrent(smooth){const n=document.querySelector('.jm-node.current')||document.querySelector('.jm-node:last-of-type');if(n)n.scrollIntoView({behavior:smooth?'smooth':'instant',block:'center'})}function watchCurrentNode(){if(jmObserver){jmObserver.disconnect();jmObserver=null}const node=document.querySelector('.jm-node.current'),btn=document.querySelector('[data-jump-current]');if(!node||!btn||typeof IntersectionObserver==='undefined'){if(btn)btn.hidden=true;return}jmObserver=new IntersectionObserver(([e])=>{btn.hidden=e.isIntersecting},{threshold:.35});jmObserver.observe(node)}function refreshMap(){const el=document.querySelector('[data-journey-map]');if(!el)return;el.outerHTML=journeyMap();watchCurrentNode();if(!document.getElementById('player')?.open){openingGate=-1;progressPending=false}}function afterJourneyRender(){watchCurrentNode();const jump=progressPending||journeyCount()>0;openingGate=-1;progressPending=false;if(jump)requestAnimationFrame(()=>scrollToCurrent(false))}
render();
function profileInfo(){return Object.assign({name:'Sofia',avatar:'/assets/profile-sofia.png',email:'responsavel@sementinha.com',plan:'Completo'},read('sementinha-profile',{}))}
function profileStats(){return {active:Object.values(journeyData.days).filter(seconds=>seconds>=ACTIVE_DAY_SECONDS).length,heard:new Set(journeyData.completed).size,total:window.STORY_CATALOG?.length||stories.length,favorites:favorites.length}}
function profilePage(){const p=profileInfo(),s=profileStats();return `<div class="profile-page"><div class="profile-intro"><h1>Meu perfil</h1><p>O cantinho da sua criança dentro da jornada.</p></div><section class="profile-child-card"><div class="profile-avatar-wrap"><img src="${p.avatar}" alt="Avatar de ${p.name}"></div><div class="profile-child-copy"><h2>${p.name}</h2><p>Pequena exploradora</p><button class="profile-edit-button" data-profile-action="edit">${icon('edit')}Editar nome e foto</button></div></section><section class="profile-stats" aria-label="Resumo da jornada"><button data-profile-action="journey"><span class="profile-stat-icon flame">🔥</span><strong>${s.active}</strong><small>${s.active===1?'dia ativo':'dias ativos'}</small></button><button data-profile-action="library"><span class="profile-stat-icon">${icon('headphones')}</span><strong>${s.heard}/${s.total}</strong><small>histórias ouvidas</small></button><button data-profile-action="favorites"><span class="profile-stat-icon heart">${icon('heart')}</span><strong>${s.favorites}</strong><small>${s.favorites===1?'favorita':'favoritas'}</small></button></section><section class="profile-options"><button data-profile-action="access"><span class="profile-option-icon">${icon('user')}</span><span><strong>Meu acesso</strong><small>Ver e-mail e acesso atual</small></span>${icon('arrow')}</button><button data-profile-action="password"><span class="profile-option-icon">${icon('lock')}</span><span><strong>Alterar senha</strong><small>Mantenha sua conta segura</small></span>${icon('arrow')}</button><button data-profile-action="logout" class="logout-option"><span class="profile-option-icon">${icon('logout')}</span><span><strong>Sair</strong><small>Encerrar sua sessão</small></span>${icon('arrow')}</button></section></div>`}
function loginView(){return `<main class="login-screen"><div class="login-card"><div class="brand">${icon('sprout')}<span class="brand-name">sementinha<em>da fé</em></span></div><h1>Volte para sua jornada</h1><p>Entre novamente para continuar ouvindo suas histórias.</p><button class="primary" data-profile-login>${icon('user')}Entrar no aplicativo</button></div></main>`}
function showProfileModal(mode){const d=document.getElementById('stage-dialog'),p=profileInfo();if(!d)return;let body='';if(mode==='edit')body=`<div class="profile-modal-body"><div class="chapter-label">Seu perfil</div><h2>Editar nome e foto</h2><div class="profile-edit-preview"><img data-avatar-preview src="${p.avatar}" alt="Prévia do avatar"><label class="profile-upload">${icon('edit')}Escolher foto<input type="file" accept="image/*" data-profile-avatar></label></div><label class="profile-field">Nome da criança<input data-profile-name value="${p.name}" maxlength="32"></label><div class="profile-modal-actions"><button data-profile-cancel>Cancelar</button><button class="primary" data-profile-save>Salvar</button></div></div>`;else if(mode==='access')body=`<div class="profile-modal-body"><div class="chapter-label">Conta conectada</div><h2>Meu acesso</h2><div class="profile-account-row"><span>E-mail cadastrado</span><strong>${p.email}</strong></div><div class="profile-account-row"><span>Plano atual</span><strong>${p.plan}</strong></div><button class="primary profile-modal-close" data-profile-cancel>Fechar</button></div>`;else if(mode==='password')body=`<div class="profile-modal-body"><div class="chapter-label">Segurança</div><h2>Alterar senha</h2><label class="profile-field">Senha atual<input type="password" data-current-password></label><label class="profile-field">Nova senha<input type="password" data-new-password></label><label class="profile-field">Confirmar nova senha<input type="password" data-confirm-password></label><div class="profile-modal-actions"><button data-profile-cancel>Cancelar</button><button class="primary" data-profile-save-password>Salvar senha</button></div></div>`;else body=`<div class="profile-modal-body"><div class="chapter-label">Sua conta</div><h2>Deseja sair da sua conta?</h2><p class="profile-modal-note">Seu progresso, favoritos, dias ativos e perfil continuarão salvos neste dispositivo.</p><div class="profile-modal-actions"><button data-profile-cancel>Cancelar</button><button class="danger-button" data-profile-confirm-logout>Sair</button></div></div>`;d.innerHTML=`<button class="icon-btn peek-close" data-profile-cancel aria-label="Fechar">${icon('close')}</button>${body}`;d.showModal()}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-profile-login')){save('sementinha-session-active',true);page='journey';render();return}if(b.dataset.profileAction){const action=b.dataset.profileAction;if(action==='journey'){page='journey';filter='Todas';query='';render();window.scrollTo({top:0,behavior:'instant'})}else if(action==='library'){page='library';filter='Todas';query='';render();window.scrollTo({top:0,behavior:'instant'})}else if(action==='favorites'){page='favorites';filter='Todas';query='';render();window.scrollTo({top:0,behavior:'instant'})}else showProfileModal(action);return}if(b.hasAttribute('data-profile-cancel')){document.getElementById('stage-dialog')?.close();return}if(b.hasAttribute('data-profile-save')){const name=document.querySelector('[data-profile-name]')?.value.trim()||'Sofia',avatar=document.querySelector('[data-avatar-preview]')?.src||profileInfo().avatar;save('sementinha-profile',Object.assign(profileInfo(),{name,avatar}));document.getElementById('stage-dialog')?.close();render();toast('Perfil atualizado com carinho.');return}if(b.hasAttribute('data-profile-save-password')){const next=document.querySelector('[data-new-password]')?.value||'',confirm=document.querySelector('[data-confirm-password]')?.value||'';if(next.length<6){toast('A nova senha precisa ter pelo menos 6 caracteres.');return}if(next!==confirm){toast('As senhas não coincidem.');return}save('sementinha-password-updated',Date.now());document.getElementById('stage-dialog')?.close();toast('Senha alterada com sucesso.');return}if(b.hasAttribute('data-profile-confirm-logout')){save('sementinha-session-active',false);document.getElementById('stage-dialog')?.close();render();return}});
app.addEventListener('change',e=>{if(!e.target.matches('[data-profile-avatar]'))return;const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const preview=document.querySelector('[data-avatar-preview]');if(preview)preview.src=reader.result};reader.readAsDataURL(file)});
